# region: sift
def sift(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: emit
def emit(xs, factor=3):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: gather
def gather(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return gather(intake(fold(digest(emit(sift(raw))))))

